function sourcedDeadlineTools(){return `<section class="degree-optimizer"><span class="eyebrow">SOURCED DATES · ${DeadlineEvidence.checked}</span><h2>Find the checkpoints that apply to you.</h2><p>Choose the college, applicant route and entry/graduation quarter. Exact calendar dates keep their published year; derived annual dates are clearly labeled for confirmation.</p><form id="deadline-finder" class="form-grid"><label>College<select name="institution">${DeadlineEvidence.calendars.map(c=>`<option>${esc(c.institution)}</option>`).join('')}</select></label><label>Applicant route<select name="track">${options(['First year','Transfer','Current UW Seattle undergraduate','Transfer / post-baccalaureate','Current student'])}</select></label><label>Quarter<select name="entry">${options(['Autumn','Winter','Spring','Summer'],'Autumn')}</select></label><label>Year<input name="year" type="number" min="2020" max="2050" value="${esc(state.profile?.startYear||2027)}" required></label><label>Major/program name<input name="program" maxlength="150" value="${esc(state.profile?.primaryProgram||state.profile?.major||'')}" placeholder="Needed for program-specific rules"></label><label>UWB transfer/post-baccalaureate program (if applicable)<select name="majorRow"><option value="">Select the exact published table row</option>${DeadlineEvidence.majorApplicationRules.map((r,i)=>`<option value="${i}">${esc(r.programLabel)}</option>`).join('')}</select></label><button class="btn">Find sourced checkpoints</button></form><div id="deadline-results" aria-live="polite"></div><details><summary>Graduation procedures — separate from commencement</summary>${DeadlineEvidence.graduationRules.map(r=>`<article class="degree-goal"><h3>${esc(r.institution)}</h3><p>${esc(r.rule||r.recommendedApplication||'')}</p>${r.steps?`<ul>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}${r.multipleAwards?`<p>${esc(r.multipleAwards)}</p>`:''}<p>${esc(r.summerCommencement||'')}</p><a href="${esc(r.source)}" target="_blank" rel="noopener">Official procedure ↗</a></article>`).join('')}</details><details><summary>Official calendars for every listed college</summary>${DeadlineEvidence.calendars.map(c=>`<p><a class="journey-secondary" href="${esc(c.currentCalendar||c.url)}" target="_blank" rel="noopener">${esc(c.institution)} ↗</a> · ${esc(c.coverage)}</p>`).join('')}</details><details><summary>Coverage gaps and source conflicts</summary><p>Some official pages remain blocked or interactive. No dates were invented for them. Closing time and time zone are unknown unless the source explicitly states them.</p>${[...DeadlineEvidence.unknowns,...DeadlineEvidence.sourceConflicts].map(r=>`<p><strong>${esc(r.institution)}:</strong> ${esc(r.reason||r.text)}</p>`).join('')}</details></section>`}
function saveSourcedDeadline(row){state.advisingDates||=[];if(state.advisingDates.length>=40)return toast('Use up to 40 saved checkpoints.');if(state.advisingDates.some(d=>d.date===row.date&&d.label===row.label&&d.institution===row.institution))return toast('That checkpoint is already on your plan.');state.advisingDates.push({label:row.label,date:row.date,institution:row.institution,cycle:row.cycle||row.entry||'',track:row.track||'Current students — verify applicability',source:row.source,dateBasis:row.dateBasis||'Source snapshot; verify applicability',closingTime:row.closingTime||'',timeZone:row.timeZone||'',scope:row.scope||''});state.advisingDates.sort((a,b)=>a.date.localeCompare(b.date));save();toast('Sourced checkpoint saved to your plan, calendar and plan image.')}
function bindSourcedDeadlines(){document.querySelector('#deadline-finder')?.addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),rows=DeadlineCore.candidates(DeadlineEvidence,f),target=document.querySelector('#deadline-results'),today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());target.innerHTML=`<h3>${rows.length} sourced checkpoints match this selection</h3>${rows.length?'':'<p>No applicable dated rule is loaded for this exact selection. Open the official calendar below; missing dates do not mean there is no deadline.</p>'}${rows.map((r,i)=>`<article class="degree-goal"><span class="eyebrow">${esc(r.deadlineType||'Calendar checkpoint')}</span><h3>${esc(r.date)} · ${esc(r.label)}</h3><p>${esc(r.cycle||r.entry)} · ${esc(r.track||'Confirm student eligibility')}</p><p>${esc(r.scope||'')}</p><p>${esc(r.dateBasis)} ${r.closingTime?'Closing time: '+esc(r.closingTime)+' '+esc(r.timeZone||'confirm time zone'):'Closing time not verified.'}</p>${r.date<today?'<p class="plan-trust-alert">This date is already past. Check another entry cycle or contact the college.</p>':''}<a class="journey-secondary" href="${esc(r.source)}" target="_blank" rel="noopener">Official source ↗</a><button class="btn" data-save-source-date="${i}">Add to my plan</button></article>`).join('')}`;target.querySelectorAll('[data-save-source-date]').forEach(b=>b.onclick=()=>saveSourcedDeadline(rows[+b.dataset.saveSourceDate]))})}
function installSourcedDeadlines(){const before=advisingPage;advisingPage=()=>before()+sourcedDeadlineTools();const beforeBind=bind;bind=()=>{beforeBind();bindSourcedDeadlines()}}
